import{_ as i,l as c,o as e,c as r,v as t,p as n,x as o,d as s,i as p,S as m}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"LSM 与 compaction","description":"","frontmatter":{"title":"LSM 与 compaction","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lsm-compaction.md","filePath":"cs/lsm-compaction.md","lastUpdated":1789023840000}'),d={name:"cs/lsm-compaction.md"};function S(h,a,_,T,b,u){const l=c("Mermaid");return e(),r("div",null,[a[1]||(a[1]=t('<h1 id="lsm-与-compaction" tabindex="-1">LSM 与 compaction <a class="header-anchor" href="#lsm-与-compaction" aria-label="Permalink to &quot;LSM 与 compaction&quot;">​</a></h1><div class="epigraph"><p>先写内存表再刷成不可变文件；compaction 把多层文件归并，用顺序写换读时的多层查找。</p><footer>—— 据 O&#39;Neil, Cheng, Gawlick and O&#39;Neil, The Log-Structured Merge-Tree, Acta Informatica 1996；Google Bigtable；RocksDB</footer></div><p><a href="/cs/art-index-db">上一课</a>给主存有序树。本课不升级 Node48。缺口是写多读少或写吞吐优先：B+ 原地更新造成随机写与页分裂。日志结构归并树（LSM）把写入变成追加：memtable 满则 freeze 成 SSTable（有序文件），后台 compaction 归并重叠键。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>随机写 SSD 也有放大与写寿命。LSM：插入/更新/删除（墓碑）进 memtable（可用跳表或 ART）；刷盘后文件不可变，简化并发（写不改旧文件）。读必须查 memtable + 各层文件，直到找到最新版本。缺口是 <strong>compaction 策略</strong>决定写放大、读放大、空间放大——下一课读放大与布隆，再下一课 leveled vs tiered。</p><p>崩溃：WAL 保护尚未刷盘的 memtable，与主干 WAL 同构，粒度是应用日志。检查点即「哪些文件是当前版本」。</p><p><span class="marginnote">O&#39;Neil et al. 1996 LSM。Bigtable / LevelDB / RocksDB 是工程谱系。本课机制，RocksDB 产品课在数据模型族再讲。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Level-0：新刷的文件可重叠。更高层：compaction 挑选重叠文件归并输出。墓碑要保留到能证明更下层无旧值才丢。快照/MVCC：compaction 不能丢掉仍被快照看见的版本——与后课 MVCC GC 接口。</p><p>节流：compaction 跟不上则写停顿（write stall）。这是 LSM 的运维不变式，不是偶发。</p>',10)),(e(),n(m,null,{default:o(()=>[p(l,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E5%86%99%22%5D%20--%3E%20MT%5B%22memtable%22%5D%0A%20%20MT%20--%3E%20SST%5B%22%E5%88%B7%E6%88%90%20SSTable%22%5D%0A%20%20SST%20--%3E%20CMP%5B%22compaction%20%E5%BD%92%E5%B9%B6%22%5D%0A%20%20R%5B%22%E8%AF%BB%22%5D%20--%3E%20MT%0A%20%20R%20--%3E%20SST%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>顺序写带宽高，代价是读走多文件、写同一键多次（每层一次）。B+ 读放大低、写随机。选择是工作负载，不是谁淘汰谁。延迟物化、列存可叠在 SST 内部格式上（后课 Parquet 是分析侧亲戚）。</p><p>并行：多 compaction 工人，注意与缓冲池争磁盘。pin-latch 模型变成文件+块缓存。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不量化布隆如何砍文件。也不把 leveled/tiered 的放大公式写完。全文倒排也可 LSM，后课。</p><p>后课默认：写走 memtable+SST+compaction。读放大与布隆：用过滤器避免打开无键文件。</p><p>不可变文件让崩溃恢复变成「丢掉未刷 memtable、重放 WAL」，结构修改比 B+ SMO 少。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LSM 用顺序刷盘与归并代替原地更新。</li><li>compaction 是持续税；跟不上则写停顿。</li><li>读放大与布隆下一课。</li><li>出处：O&#39;Neil et al. 1996；Bigtable；RocksDB 设计。</li></ul>',9))])}const M=i(d,[["render",S]]);export{f as __pageData,M as default};
